// Generates src/tokens/generated.css from src/tokens/tokens.ts (the single token source).
// Usage: node scripts/build_tokens.mjs        -> write the file
//        node scripts/build_tokens.mjs --check -> exit 1 if the file is out of date
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const tokens = await import('../src/tokens/tokens.ts');
const out = fileURLToPath(new URL('../src/tokens/generated.css', import.meta.url));

const lines = [
  '/* Generated by scripts/build_tokens.mjs from tokens.ts. Do not edit. */',
  '@theme static {',
];
lines.push('  --color-*: initial;');
for (const [name, value] of Object.entries(tokens.colors))
  lines.push(`  --color-${name}: ${value};`);
tokens.categoryPalette.forEach((c, i) => {
  lines.push(`  --color-cat-${i + 1}-fg: ${c.fg};`);
  lines.push(`  --color-cat-${i + 1}-bg: ${c.bg};`);
  lines.push(`  --color-cat-${i + 1}-mark: ${c.mark};`);
});
lines.push(`  --font-serif: ${tokens.fonts.serif};`);
lines.push(`  --font-sans: ${tokens.fonts.sans};`);
lines.push(`  --font-mono: ${tokens.fonts.mono};`);
lines.push(`  --radius-control: ${tokens.radius.control};`);
lines.push(`  --radius-card: ${tokens.radius.card};`);
lines.push(`  --radius-chip: ${tokens.radius.chip};`);
lines.push(`  --shadow-popover: ${tokens.shadow.popover};`);
lines.push(`  --ease-out-soft: ${tokens.motion.ease};`);
for (const key of ['fast', 'base', 'slow', 'chart']) {
  lines.push(`  --duration-${key}: ${tokens.motion[key]}ms;`);
}
for (const [name, [size, lh, weight]] of Object.entries(tokens.typeScale)) {
  lines.push(`  --text-${name}: ${size}px;`);
  lines.push(`  --text-${name}--line-height: ${lh};`);
  lines.push(`  --text-${name}--font-weight: ${weight};`);
}
lines.push('}', '');
const css = lines.join('\n');

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(out, 'utf8');
  } catch {
    // missing file is reported below
  }
  if (current !== css) {
    console.error('generated.css is out of date: run node scripts/build_tokens.mjs');
    process.exit(1);
  }
  console.log('tokens: generated.css is up to date');
} else {
  writeFileSync(out, css, 'utf8');
  console.log(`tokens: wrote ${out}`);
}
